def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full rows and columns are the divider lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    divider = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]

    # The background is the most frequent color other than the divider.
    counts = {}
    for row in grid:
        for value in row:
            if value != divider:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    result = []
    for i in range(len(rb) - 1):
        out_row = []
        for j in range(len(cb) - 1):
            marks = sum(
                grid[r][c] != divider and grid[r][c] != background
                for r in range(rb[i] + 1, rb[i + 1])
                for c in range(cb[j] + 1, cb[j + 1])
            )
            out_row.append(1 if marks == 2 else background)
        result.append(out_row)
    return result
